44.query:
fetch dt.system.events, from: -7d
| filter event.kind == "BILLING_USAGE_EVENT"
| filter in(event.type, {
    "AI Function Standard Call", "Standard Function Call"
  })
| dedup {event.id, event.type}
| fieldsAdd hour = bin(timestamp, 1h)
| summarize billed_calls = sum(billed_invocations), by: {hour, event.type}
//| fieldsAdd billed_invocations = round(toDouble(billed_bytes), decimals: 3)
| fields hour, event.type, billed_calls
| sort hour asc, event.type asc

50.query:
fetch dt.system.events, scanLimitGBytes: -1
| filter event.kind == "BILLING_USAGE_EVENT"
| filter event.type == "AI Units"
| summarize {
    usage.quantity.billable = takeAny(usage.quantity.billable)
  }, by: {
    startHour = bin(timestamp, 1h),
    event.id,
    tool,
    user.id,
    user.email,
    caller.app.id,
    caller.service.id,
    caller.type,
    dt.app.id,
    workflow.execution.id
  }
| fieldsAdd workflow_triggered = if(isNotNull(workflow.execution.id),true,else:false)  
| summarize {
    Units = sum(if(exists(usage.quantity.billable), usage.quantity.billable, else: 1))
  }, by: {
    { User=user.email, Tool=tool }
  }
| sort Units desc
| limit 20

65.query:
fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT"
| filter ai_generated == true
| filter in(event.type, {
    "Log Management & Analytics - Query",
    "Events - Query",
    "Traces - Query"  })
| dedup {event.id, event.type}
| fieldsAdd attribution = coalesce(client.source, client.application_context, "unknown")
| fieldsAdd query_type =
    if(startsWith(event.type, "Events"), "Events", 
    else: if(startsWith(event.type, "Log Management"), "Logs", 
    else: if(startsWith(event.type, "Traces "), "Traces", 
    else: "Other")))

| summarize {
    billed_bytes = sum(billed_bytes),
    query_count  = countDistinct(query_id)
}, by: {query_type, attribution, user.email, client.function_context}
| fieldsAdd billed_gib = round(toDouble(billed_bytes) / 1073741824, decimals: 3)
| fieldsAdd avg_billed_gib = billed_gib/query_count
| sort billed_gib desc
| fields User=user.email, `Query type`=query_type, `Billed GiB`= billed_gib, `Query count` = query_count, `Avg billed GiB` = avg_billed_gib
| limit 20

