73.query:
fetch dt.system.events
| filter event.kind == "BILLING_USAGE_EVENT"
| filter in(event.type, {"Log Management & Analytics - Query","Events - Query","Traces - Query","Digital Experience Monitoring - Query","AI Function Standard Call","AI Units"})
| dedup event.id
| fieldsAdd capability = if(event.type == "Log Management & Analytics - Query", "Log Query",
                          else: if(event.type == "Events - Query", "Events Query",
                          else: if(event.type == "AI Function Standard Call", "Standard Function Calls",
                          else: if(event.type == "AI Units", "AI Units",
                          else: if(event.type == "Traces - Query", "Traces Query")))))
| fieldsAdd cost =   if(event.type == "Log Management & Analytics - Query" AND ai_generated == true, toDouble(coalesce(billed_bytes, 0)) / 1073741824.0 * 0.0035,
    else: if(event.type =="Events - Query" AND ai_generated == true, toDouble(coalesce(billed_bytes, 0)) / 1073741824.0 * 0.0035, 
    else: if(event.type == "Traces - Query" AND ai_generated == true, toDouble(coalesce(billed_bytes, 0)) / 1073741824.0 * 0.0035,
    else: if(event.type == "AI Units", toDouble(coalesce(usage.quantity.billable, 0)) * 0.10, 
    else: if(event.type == "AI Function Standard Call", toDouble(coalesce(billed_invocations, 0)) * 0.001)))))
| summarize cost = sum(cost), by: {capability}

74.query:
fetch dt.system.events, scanLimitGBytes: -1
| filter event.kind == "BILLING_USAGE_EVENT"
| filter event.type == "AI Units"
| dedup event.id| filter in(event.type, array("AI Units", "AI Function Standard Call"))
| filter isNotNull(workflow.execution.id)
| dedup event.id
| sort timestamp asc
| summarize {
    Units = sum(if(exists(usage.quantity.billable), usage.quantity.billable, else: 1)),
    steps = count(), 
    sequence = collectArray(tool)
  }, by: { workflow.id, workflow.execution.id, user.email }
| summarize { 
    Units = sum(Units),
    //workflows = countDistinctExact(workflow.id), 
    workflow_execs = countDistinctExact(workflow.execution.id)
  }, by: { workflow.id, user.email }
| fieldsAdd link.to.workflow = concat("[Link](/ui/apps/dynatrace.automations/workflows/", workflow.id, "?view=live)")
| sort Units desc
| fields `Workflow ID` = workflow.id, `User` = user.email, `Link to workflow` = link.to.workflow, Units, `Workflow executions` = workflow_execs
